import { Component, Input, forwardRef, ElementRef, HostListener, inject } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule, Validator, AbstractControl, ValidationErrors, NG_VALIDATORS } from '@angular/forms';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-searchable-select',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './searchable-select.component.html',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => SearchableSelectComponent),
      multi: true
    },
    {
      provide: NG_VALIDATORS,
      useExisting: forwardRef(() => SearchableSelectComponent),
      multi: true
    }
  ],
  host: {
    class: 'flex-grow-1'
  }
})
export class SearchableSelectComponent implements ControlValueAccessor, Validator {
  @Input() options: string[] = [];
  @Input() placeholder = 'Selecciona una opción';

  filteredOptions: string[] = [];
  searchTerm = '';
  isDropdownOpen = false;
  selectedValue = '';

  private elRef = inject(ElementRef);

  onChange: (value: string) => void = () => { /* noop */ };
  onTouched: () => void = () => { /* noop */ };

  writeValue(value: string): void {
    this.selectedValue = value;
    this.searchTerm = value;
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  validate(control: AbstractControl): ValidationErrors | null {
    if (!control.value) {
      return null; // Don't validate empty values, let `required` validator handle it
    }
    if (this.options && !this.options.includes(control.value)) {
      return { invalidOption: true };
    }
    return null;
  }

  @HostListener('document:click', ['$event'])
  handleClick(event: Event): void {
    const clickedInside = this.elRef.nativeElement.contains(event.target);

    if (!clickedInside && this.isDropdownOpen) {
      this.isDropdownOpen = false;
    }
  }

  filterOptions(): void {
    if (this.searchTerm) {
      this.filteredOptions = this.options.filter(option =>
        option.toLowerCase().includes(this.searchTerm.toLowerCase())
      );
    } else {  
      this.filteredOptions = this.options;
    }
  }

  toggleDropdown(): void {
    this.isDropdownOpen = !this.isDropdownOpen;
    if (this.isDropdownOpen) {
      this.filteredOptions = this.options;
    }
  }

  selectOption(option: string): void {
    this.selectedValue = option;
    this.searchTerm = option;
    this.onChange(this.selectedValue);
    this.onTouched();
    this.isDropdownOpen = false;
  }

  onKeyDown(event: KeyboardEvent, option: string): void {
    if (event.key === 'Enter' || event.key === ' ') {
      this.selectOption(option);
    }
  }

  onSearchTermChange(): void {
    this.onChange(this.searchTerm);
    this.isDropdownOpen = true;
    this.filterOptions();
  }
}
