import { Component, Input, forwardRef } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-multi-select-pills',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './multi-select-pills.component.html',
  styleUrls: ['./multi-select-pills.component.css'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MultiSelectPillsComponent),
      multi: true
    }
  ]
})
export class MultiSelectPillsComponent implements ControlValueAccessor {
  @Input() options: string[] = [];

  selectedOptions: string[] = [];

  onChange: (value: string[]) => void = () => { /* noop */ };
  onTouched: () => void = () => { /* noop */ };

  writeValue(value: string[]): void {
    this.selectedOptions = value || [];
  }

  registerOnChange(fn: (value: string[]) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  toggleSelection(option: string): void {
    if (this.selectedOptions.includes(option)) {
      this.selectedOptions = this.selectedOptions.filter(opt => opt !== option);
    } else {
      this.selectedOptions.push(option);
    }
    this.onChange(this.selectedOptions);
    this.onTouched();
  }

  isSelected(option: string): boolean {
    return this.selectedOptions.includes(option);
  }
}
