// Define specific interfaces for the form structure
export interface CustomFormField {
    key: string;
    label: string;
    placeholder?: string;
    type?: 'text' | 'email' | 'number' | 'textarea' | 'file' | 'multiple-select' | 'pills-select' | 'searchable-select';
    options?: string[];
    validator?: { 
        required?: boolean; 
        email?: boolean; 
        min?: number; 
        max?: number; 
        pattern?: string;
    };
    style?: { div?: string; };
    accept?: string;
    iconClass?: string;
    auxiliaryText?: string;
    hidden?: boolean;
    errorMessages?: { [key: string]: string; };
    maxFileSize?: number;
}

export interface CustomFormSubsection {
    title: string;
    iconClass?: string;
    fields: CustomFormField[];
}

export interface CustomFormGroup {
    title: string;
    subsections: CustomFormSubsection[];
}

export interface CustomFormDefinition {
    title: string;
    forms: CustomFormGroup[][];
}

