import { Component, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule, AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { startWith } from 'rxjs/operators';
import { Subscription } from 'rxjs'; // Import Subscription
import { StepWizardComponent } from '../../../shared/step-wizard/step-wizard.component';
import { FormNavigationComponent } from '../../../shared/form-navigation/form-navigation.component';
import { FormFieldComponent } from '../../../shared/form-field/form-field.component';
import { FormDefinition } from '../../../shared/interfaces/form-section.interface';
import { FORM_DEFINITION, CustomFormSubsection, CustomFormField } from './formulario-inhibidores-config.form';
import { FormularioInhibidoresService } from './formulario-inhibidores.service';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

@Component({
    selector: 'app-formulario-inhibidores-form',
    imports: [CommonModule, ReactiveFormsModule, StepWizardComponent, FormNavigationComponent, FormFieldComponent],
    templateUrl: './formulario-inhibidores-form.html'
})
export class FormularioInhibidoresForm implements OnInit {
    formDefinition: FormDefinition = FORM_DEFINITION;
    inhibidoresForm!: FormGroup;
    currentSection = 0;
    formSubmitted = false;
    companyType: string | null = null;
    private subscriptions: Subscription[] = []; // To manage subscriptions

    // Services
    private fb = inject(FormBuilder);
    private formularioService = inject(FormularioInhibidoresService);
    private storage = inject(LocalStorageService);

    isSubmitting: boolean = false;
    
    ngOnInit(): void {
        this._buildForm();
        this._loadUserInformation();
        this.loadOptions();
        this.setupConditionalLogic();
        this.scrollToTop();

        // Subscribe to num_empleados changes
        const numEmpleadosControl = this.inhibidoresForm.get('section0.num_empleados');
        if (numEmpleadosControl) {
            this.subscriptions.push(numEmpleadosControl.valueChanges.pipe(
                startWith(numEmpleadosControl.value)
            ).subscribe(value => {
                this._updateCompanyType(Number(value));
            }));
        }
    }

    ngOnDestroy(): void {
        this.subscriptions.forEach(sub => sub.unsubscribe());
    }


    private _buildForm(): void {
        this.inhibidoresForm = this.fb.group({});
        this.formDefinition.forms.forEach((section, index) => {
            const sectionGroup = this.fb.group({});
            section.forEach(formElement => {
                formElement.subsections.forEach(subsection => {
                    subsection.fields.forEach(field => {
                        sectionGroup.addControl(field.key, this._createControl(field));
                    });
                });
            });
            this.inhibidoresForm.addControl(`section${index}`, sectionGroup);
        });
    }

    private _loadUserInformation(): void {
        const user = this.storage.getUser();
        if (user) {
            this.inhibidoresForm.get('section0')?.patchValue({
                nombre_solicitante: user.user.name,
                email_solicitante: user.user.email
            });
        }
    }

    private _createControl(field: CustomFormField): AbstractControl {
        const validators = this._getValidators(field);
        const initialValue = (field.type === 'pills-select' || field.type === 'file') ? null : '';
        return this.fb.control(initialValue, validators);
    }

    private _getValidators(field: CustomFormField): ValidatorFn[] {
        const validators: ValidatorFn[] = [];
        const fieldValidator = field.validator;
        if (fieldValidator?.required) validators.push(Validators.required);
        if (fieldValidator?.email) validators.push(Validators.email);
        if (fieldValidator?.min !== undefined) validators.push(Validators.min(fieldValidator.min));
        if (fieldValidator?.max !== undefined) validators.push(Validators.max(fieldValidator.max));
        if (fieldValidator?.pattern) validators.push(Validators.pattern(fieldValidator.pattern));
        return validators;
    }

    private async loadOptions(): Promise<void> {
        await this.formularioService.loadOptions(this.findFieldDefinition.bind(this));
    }

    scrollToTop(): void {
        document.getElementById('main-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    setupConditionalLogic(): void {
        const s1 = (key: string) => `section1.${key}`;

        this._setupConditionalVisibility(this.getControl(s1('giro_principal')), this.getControl(s1('otro_giro')), this.findFieldDefinition('otro_giro'), value => value === 'Ninguna de las anteriores');
        this._setupConditionalVisibility(this.getControl(s1('es_miembro_asociacion')), this.getControl(s1('asociacion')), this.findFieldDefinition('asociacion'), value => value === 'Sí');
        this._setupConditionalVisibility(this.getControl(s1('asociacion')), this.getControl(s1('otra_asociacion')), this.findFieldDefinition('otra_asociacion'), value => value === 'Ninguna de las anteriores');
        this._setupConditionalVisibility(this.getControl(s1('relacionado_gobierno')), this.getControl(s1('nivel_gobierno')), this.findFieldDefinition('nivel_gobierno'), value => value === 'Sí', { isMultiSelect: true });
        this._setupConditionalVisibility(this.getControl(s1('nivel_gobierno')), this.getControl(s1('otro_nivel_gobierno')), this.findFieldDefinition('otro_nivel_gobierno'), value => Array.isArray(value) && value.includes('No sé'));
        this._setupConditionalVisibility(this.getControl(s1('relacionado_sitio_web')), this.getControl(s1('limitantes_sitio_web')), this.findFieldDefinition('limitantes_sitio_web'), value => value === 'Sí', { isMultiSelect: true });
        this._setupConditionalVisibility(this.getControl(s1('limitantes_sitio_web')), this.getControl(s1('otra_limitante_sitio_web')), this.findFieldDefinition('otra_limitante_sitio_web'), value => Array.isArray(value) && value.includes('Ninguna de las anteriores'));
        this._setupConditionalVisibility(this.getControl(s1('relacionado_leyes')), this.getControl(s1('leyes_regulaciones')), this.findFieldDefinition('leyes_regulaciones'), value => value === 'Sí', { isMultiSelect: true });
        this._setupConditionalVisibility(this.getControl(s1('leyes_regulaciones')), this.getControl(s1('otra_ley_regulacion')), this.findFieldDefinition('otra_ley_regulacion'), value => Array.isArray(value) && value.includes('Ninguna de las anteriores'));
        this._setupConditionalVisibility(this.getControl(s1('relacionado_tramites')), this.getControl(s1('tramites')), this.findFieldDefinition('tramites'), value => value === 'Sí', { isMultiSelect: true });
        this._setupConditionalVisibility(this.getControl(s1('relacionado_mercado')), this.getControl(s1('limitantes_mercado')), this.findFieldDefinition('limitantes_mercado'), value => value === 'Sí', { isMultiSelect: true });
        this._setupConditionalVisibility(this.getControl(s1('limitantes_mercado')), this.getControl(s1('otra_limitante_mercado')), this.findFieldDefinition('otra_limitante_mercado'), value => Array.isArray(value) && value.includes('Otro'));
    }

    private _setupConditionalVisibility(sourceControl: AbstractControl | null, targetControl: AbstractControl | null, targetFieldDef: CustomFormField | undefined, showCondition: (value: any) => boolean, options: { required?: boolean, isMultiSelect?: boolean } = {}) {
        if (!sourceControl || !targetControl || !targetFieldDef) return;

        const { required = true, isMultiSelect = false } = options;

        sourceControl.valueChanges.pipe(startWith(sourceControl.value)).subscribe(value => {
            if (showCondition(value)) {
                targetControl.enable();
                if (required) targetControl.setValidators(Validators.required);
                targetFieldDef.hidden = false;
            } else {
                targetControl.disable();
                targetControl.clearValidators();
                targetControl.setValue(isMultiSelect ? [] : '');
                targetFieldDef.hidden = true;
            }
            targetControl.updateValueAndValidity();
        });
    }

    get sectionProgress(): number {
        const currentControls = this.currentFormGroup.controls;
        const enabledControls = Object.values(currentControls).filter(c => c.enabled);
        if (enabledControls.length === 0) return 0;
        const validControls = enabledControls.filter(c => c.valid).length;
        return (validControls / enabledControls.length) * 100;
    }

    get isNextButtonDisabled(): boolean {
        return false;
    }

    get currentFormGroup(): FormGroup {
        return this.inhibidoresForm.get('section' + this.currentSection) as FormGroup;
    }

    countVisibleFields(subsection: CustomFormSubsection): number {
        return subsection.fields.filter(field => !field.hidden).length;
    }

    nextSection() {
        if (this.currentFormGroup.valid) {
            this.missingFields = []; // Clear errors if valid
            if (this.currentSection < this.formDefinition.forms.length - 1) {
                this.currentSection++;
                this.scrollToTop();
            } else {
                this.submitForm();
            }
        } else {
            this.currentFormGroup.markAllAsTouched();
            this.updateMissingFields('current');
            this.scrollToTop();
        }
    }

    previousSection() {
        if (this.currentSection > 0) {
            this.currentSection--;
            this.scrollToTop();
            this.missingFields = []; // Clear errors when going back
        }
    }

    async submitForm() {
        if (this.inhibidoresForm.invalid) {
            this.inhibidoresForm.markAllAsTouched();
            this.updateMissingFields('all');
            return;
        }

        this.isSubmitting = true;
        try {
            const formValue = this.inhibidoresForm.getRawValue();
            const success = await this.formularioService.submitForm(formValue);

            if (success) {
                this.formSubmitted = true;
                this.scrollToTop();
            } else {
                console.error('Submission failed.');
            }
        } finally {
            this.isSubmitting = false;
        }
    }

    private findFieldDefinition(key: string): CustomFormField | undefined {
        for (const section of this.formDefinition.forms) {
            for (const formElement of section) {
                for (const subsection of formElement.subsections) {
                    const field = subsection.fields.find(f => f.key === key);
                    if (field) return field;
                }
            }
        }
        return undefined;
    }

    private getControl(path: string): AbstractControl | null {
        return this.inhibidoresForm.get(path);
    }

    integerValidator(control: AbstractControl): ValidationErrors | null {
        if (control.value === null || control.value === undefined || control.value === '') {
            return null;
        }
        const isInteger = Number.isInteger(Number(control.value));
        return isInteger ? null : { 'integer': true };
    }

    private _updateCompanyType(numEmployees: number | null): void {
        if (numEmployees === null || numEmployees < 0) {
            this.companyType = null;
        } else if (numEmployees >= 0 && numEmployees <= 10) {
            this.companyType = 'Micro';
        } else if (numEmployees >= 11 && numEmployees <= 50) {
            this.companyType = 'Pequeña';
        } else if (numEmployees >= 51 && numEmployees <= 250) {
            this.companyType = 'Mediana';
        } else {
            this.companyType = 'Grande';
        }
    }

    missingFields: string[] = [];

    private updateMissingFields(scope: 'all' | 'current' = 'all') {
        this.missingFields = [];
        this.formDefinition.forms.forEach((section, sectionIndex) => {
            // If scope is current, skip other sections
            if (scope === 'current' && sectionIndex !== this.currentSection) {
                return;
            }

            section.forEach(formElement => {
                formElement.subsections.forEach(subsection => {
                    subsection.fields.forEach(field => {
                        const control = this.inhibidoresForm.get(`section${sectionIndex}.${field.key}`);
                        if (control && control.invalid && !field.hidden) {
                            this.missingFields.push(`El campo ${field.label} falta de ser llenado`);
                        }
                    });
                });
            });
        });
    }
}