import { Component, Input } from '@angular/core';
import { FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { MultiSelectPillsComponent } from '../multi-select-pills/multi-select-pills.component';
import { SearchableSelectComponent } from '../searchable-select/searchable-select.component';
import { FormField } from '../interfaces/form-section.interface';

@Component({
  selector: 'app-form-field',
  imports: [CommonModule, ReactiveFormsModule, MultiSelectPillsComponent, SearchableSelectComponent],
  templateUrl: './form-field.component.html',
  standalone: true
})
export class FormFieldComponent {
  @Input() field!: FormField;
  @Input() formGroup!: FormGroup;
  @Input() maxFileSize: number = 1; // Default max file size to 1MB

  isFieldRequired(): boolean {
    const control = this.formGroup.get(this.field.key);
    return control?.hasValidator(Validators.required) ?? false;
  }

  onFileChange(event: Event): void {
    const element = event.currentTarget as HTMLInputElement;
    const fileList: FileList | null = element.files;

    if (fileList && fileList.length > 0) {
      const file = fileList[0];
      const fileSizeInMB = file.size / (1024 * 1024);
      const fileExtension = file.name.split('.').pop()?.toLowerCase();
      const allowedExtensions = this.field.accept?.toLowerCase().split(',').map(ext => ext.trim().substring(1));

      let isExtensionAllowed = false;
      if(allowedExtensions && fileExtension) {
        isExtensionAllowed = allowedExtensions.includes(fileExtension);
      }

      if (this.field.accept && !isExtensionAllowed) {
        this.formGroup.get(this.field.key)?.setErrors({ 'invalidFileType': true });
        this.formGroup.get(this.field.key)?.markAsTouched();
        element.value = '';
        return;
      }

      if (fileSizeInMB > this.maxFileSize) {
        this.formGroup.get(this.field.key)?.setErrors({ 'maxFileSize': true });
        this.formGroup.get(this.field.key)?.markAsTouched();
        element.value = '';
        return;
      }

      this.formGroup.get(this.field.key)?.setValue(fileList);
      if (this.formGroup.get(this.field.key)?.hasError('maxFileSize') || this.formGroup.get(this.field.key)?.hasError('invalidFileType')) {
        this.formGroup.get(this.field.key)?.updateValueAndValidity();
      }
    } else {
      this.formGroup.get(this.field.key)?.setValue(null);
    }
  }
}
