import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { GiroPrincipalService } from '../../../controllers/giro-empresas.service';
import { LimitanteSitioWebService } from '../../../controllers/limitante-sitio-web.service';
import { LimitanteMercadoService } from '../../../controllers/limitantes-mercado.service';
import { MunicipiosService } from '../../../controllers/municipios.service';
import { NivelGobiernoService } from '../../../controllers/nivel-gobierno.service';
import { OrganizacionService } from '../../../controllers/organizacion.service';
import { ProblemaRegulacionService } from '../../../controllers/problema-regulacion.service';
import { ProblemaTramiteService } from '../../../controllers/problema-tramite.service';
import { SuperService } from '../../../controllers/super.service';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { Municipio } from '../../../models/municipio.model';
import { GiroPrincipal } from '../../../models/giro-principal.model';
import { Asociacion } from '../../../models/solicitud.model';
import { CustomFormField } from './formulario-inhibidores-config.form';

export interface FormOptions {
    municipios: Municipio[];
    girosPrincipales: GiroPrincipal[];
    asociaciones: Asociacion[];
    nivelesGobierno: any[];
    allLimitantesSitioWeb: any[];
    problemasRegulacion: any[];
    problemasTramite: any[];
    allLimitantesMercado: any[];
}

interface OptionMapping {
    service: SuperService<any>;
    key: string;
    type?: CustomFormField['type'];
    add?: string;
    dataStoreKey: keyof FormOptions;
}

@Injectable({
    providedIn: 'root'
})
export class FormularioInhibidoresService {
    private municipiosService = inject(MunicipiosService);
    private giroPrincipalService = inject(GiroPrincipalService);
    private organizacionService = inject(OrganizacionService);
    private nivelGobiernoService = inject(NivelGobiernoService);
    private limitanteSitioWebService = inject(LimitanteSitioWebService);
    private problemaRegulacionService = inject(ProblemaRegulacionService);
    private problemaTramiteService = inject(ProblemaTramiteService);
    private limitanteMercadoService = inject(LimitanteMercadoService);
    private solicitudService = inject(SolicitudService);
    private apiService = inject(ApiServiceService);

    // Store loaded options
    options: FormOptions = {
        municipios: [],
        girosPrincipales: [],
        asociaciones: [],
        nivelesGobierno: [],
        allLimitantesSitioWeb: [],
        problemasRegulacion: [],
        problemasTramite: [],
        allLimitantesMercado: []
    };

    async loadOptions(findFieldDefinition: (key: string) => CustomFormField | undefined): Promise<void> {
        const optionMappings: { [key: string]: OptionMapping } = {
            'municipio': { service: this.municipiosService, key: 'nombre', dataStoreKey: 'municipios', type: 'searchable-select' },
            'giro_principal': { service: this.giroPrincipalService, key: 'nombre', dataStoreKey: 'girosPrincipales' },
            'asociacion': { service: this.organizacionService, key: 'nombre', dataStoreKey: 'asociaciones' },
            'nivel_gobierno': { service: this.nivelGobiernoService, key: 'nombre', dataStoreKey: 'nivelesGobierno' },
            'limitantes_sitio_web': { service: this.limitanteSitioWebService, key: 'descripcion', dataStoreKey: 'allLimitantesSitioWeb' },
            'leyes_regulaciones': { service: this.problemaRegulacionService, key: 'descripcion', dataStoreKey: 'problemasRegulacion' },
            'tramites': { service: this.problemaTramiteService, key: 'descripcion', dataStoreKey: 'problemasTramite' },
            'limitantes_mercado': { service: this.limitanteMercadoService, key: 'descripcion', dataStoreKey: 'allLimitantesMercado' }
        };

        const promises = Object.entries(optionMappings).map(([key, mapping]) => this._loadFieldOptions(key, mapping, findFieldDefinition));
        await Promise.all(promises);
    }

    private async _loadFieldOptions(fieldKey: string, mapping: OptionMapping, findFieldDefinition: (key: string) => CustomFormField | undefined): Promise<void> {
        const field = findFieldDefinition(fieldKey);
        if (!field) {
            console.warn(`Field definition not found for key: ${fieldKey}`);
            return;
        }

        try {
            const items = await mapping.service.all();
            (this.options as any)[mapping.dataStoreKey] = items;

            field.options = items.map((item: any) => item[mapping.key]);
            if (mapping.add) {
                field.options.push(mapping.add);
            }
            if (mapping.type) {
                field.type = mapping.type;
            }
        } catch (error) {
            console.error(`Error loading options for ${field.key}:`, error);
            field.options = [];
        }
    }

    async submitForm(formValue: any): Promise<boolean> {
        const { section0, section1, section2 } = formValue;

        const payload = {
            nombre_solicitante: section0.nombre_solicitante,
            puesto_solicitante: section0.puesto_solicitante,
            email_solicitante: section0.email_solicitante,
            nombre_empresa: section0.nombre_empresa,
            num_empleados: Number(section0.num_empleados),
            ano_inicio_operaciones: section0.ano_inicio_operaciones,
            otro_giro: section1.otro_giro || null,
            es_miembro_asociacion: section1.es_miembro_asociacion,
            otra_asociacion: section1.otra_asociacion || null,
            relacionado_gobierno: section1.relacionado_gobierno,
            otro_nivel_gobierno: section1.otro_nivel_gobierno || null,
            relacionado_sitio_web: section1.relacionado_sitio_web,
            otra_limitante_sitio_web: section1.otra_limitante_sitio_web || null,
            relacionado_leyes: section1.relacionado_leyes,
            relacionado_tramites: section1.relacionado_tramites,
            relacionado_mercado: section1.relacionado_mercado,
            otra_limitante_mercado: section1.otra_limitante_mercado || null,
            descripcion_limitante: section2.descripcion_limitante,
            propuesta_solucion: section2.propuesta_solucion || null,
            municipio_id: this._getIdByPropertyValue(this.options.municipios, section0.municipio, 'nombre'),
            giro_principal_id: this._getIdByPropertyValue(this.options.girosPrincipales, section1.giro_principal, 'nombre'),
            asociacion_id: this._getIdByPropertyValue(this.options.asociaciones, section1.asociacion, 'nombre'),
            niveles_gobierno: this._getIdsByPropertyValues(this.options.nivelesGobierno, section1.nivel_gobierno, 'nombre'),
            limitantes_sitio_web: this._getIdsByPropertyValues(this.options.allLimitantesSitioWeb, section1.limitantes_sitio_web, 'descripcion'),
            problemas_regulacion: this._getIdsByPropertyValues(this.options.problemasRegulacion, section1.leyes_regulaciones, 'descripcion'),
            problemas_tramite: this._getIdsByPropertyValues(this.options.problemasTramite, section1.tramites, 'descripcion'),
            limitantes_mercado: this._getIdsByPropertyValues(this.options.allLimitantesMercado, section1.limitantes_mercado, 'descripcion'),
        };

        const formData = this._createFormData(payload, section2);

        try {
            const response = await firstValueFrom(this.apiService.postFormData(this.solicitudService.url(), formData));
            return response.status;
        } catch (error) {
            console.error('Error during submission:', error);
            return false;
        }
    }

    private _createFormData(payload: any, section2: any): FormData {
        const formData = new FormData();
        Object.entries(payload).forEach(([key, value]) => {
            if (Array.isArray(value)) {
                value.forEach(item => formData.append(`data[${key}][]`, item));
            } else if (value !== null && value !== undefined) {
                formData.append(`data[${key}]`, String(value));
            }
        });

        this._appendFileToFormData(formData, 'data[archivo_limitante]', section2.archivo_limitante);
        this._appendFileToFormData(formData, 'data[archivo_propuesta]', section2.archivo_propuesta);
        return formData;
    }

    private _appendFileToFormData(formData: FormData, fieldName: string, fileValue: any) {
        if (fileValue instanceof File) {
            formData.append(fieldName, fileValue);
        } else if (fileValue instanceof FileList && fileValue.length > 0) {
            formData.append(fieldName, fileValue[0]);
        } else if (Array.isArray(fileValue) && fileValue[0] instanceof File) {
            formData.append(fieldName, fileValue[0]);
        }
    }

    private _getIdByPropertyValue(items: any[], value: any, propertyName: string): number | undefined {
        if (!items || value === null || value === undefined) return undefined;
        const found = items.find(item => item[propertyName] === value);
        return found ? found.id : undefined;
    }

    private _getIdsByPropertyValues(items: any[], values: any[], propertyName: string): number[] {
        if (!items || !Array.isArray(values) || values.length === 0) return [];
        const valueSet = new Set(values);
        return items
            .filter(item => valueSet.has(item[propertyName]))
            .map(item => item.id);
    }
}
