import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-form-navigation',
  imports: [CommonModule],
  templateUrl: './form-navigation.component.html'
})
export class FormNavigationComponent {
  @Input() currentSection = 0;
  @Input() totalSections = 0;
  @Input() isNextButtonDisabled = false;
  @Input() isFormInvalid = false;
  @Input() sectionProgress = 0;
  @Input() disableSubmitOnInvalid = true;
  @Input() isSubmitting = false;

  @Output() next = new EventEmitter<void>();
  @Output() previous = new EventEmitter<void>();
  @Output() submitForm = new EventEmitter<void>();
}
